<script setup lang="ts">
import { ref } from 'vue'; import { ElMessage } from 'element-plus'; import { UploadFilled } from '@element-plus/icons-vue'; import { api } from '../api'
const file=ref<File>(); const type=ref('general'); const loading=ref(false); const result=ref<any>()
async function run(){if(!file.value)return ElMessage.warning('请选择合同文件'); loading.value=true;const form=new FormData();form.append('合同文件',file.value);form.append('合同类型',type.value);try{result.value=(await api.post('/reviews',form)).data;ElMessage.success('审查完成')}catch(e:any){ElMessage.error(e.response?.data?.detail||'审查失败')}finally{loading.value=false}}
const onChange=(upload:any)=>{file.value=upload.raw}
</script>
<template><div class="page-head"><div><h1>智能审查工作台</h1><p>协调者、提取者、合规审查与修改 Agent 协同执行</p></div></div><section class="review-setup"><div class="upload-zone"><el-upload drag :auto-upload="false" :limit="1" accept=".pdf,.doc,.docx,.png,.jpg,.jpeg,.tif,.tiff,.bmp" :on-change="onChange"><el-icon class="upload-icon"><UploadFilled/></el-icon><div>拖放合同文件到此处，或点击选择</div><small>支持 PDF、Word、扫描图片，单文件不超过 50 MB</small></el-upload></div><div class="review-options"><label>合同类型</label><el-select v-model="type"><el-option label="通用合同" value="general"/><el-option label="采购合同" value="purchase"/><el-option label="销售合同" value="sales"/><el-option label="劳动合同" value="employment"/><el-option label="租赁合同" value="lease"/><el-option label="保密协议" value="nda"/><el-option label="服务合同" value="service"/></el-select><p>Agent 协同：要素提取 · 合规校验 · 风险评分 · 条款优化</p><el-button type="primary" size="large" :loading="loading" @click="run">开始审查</el-button></div></section><section v-if="result" class="results"><div class="result-summary"><div><span>总体风险</span><strong>{{result.final_report?.总体风险等级}}</strong></div><div><span>风险评分</span><strong>{{result.final_report?.风险评分?.风险分}}</strong></div><div><span>风险点</span><strong>{{result.risk_findings.length}}</strong></div><router-link v-if="file?.type==='application/pdf'" :to="`/reader/${result.review_id}`"><el-button>进入双栏阅读器</el-button></router-link></div><div class="risk-list"><details v-for="risk in result.risk_findings" :key="risk.风险编号"><summary><el-tag :type="risk.风险等级==='高'?'danger':risk.风险等级==='中'?'warning':'success'">{{risk.风险等级}}</el-tag><b>{{risk.短标题||risk.风险类别}}</b><span>{{risk.风险标题}}</span></summary><div class="risk-detail"><p>{{risk.问题说明}}</p><p><b>修改方向：</b>{{risk.修改方向}}</p></div></details></div></section></template>
